import React, { useState } from 'react';
import { useNavigate } from 'react-router-dom';
import { useAuth } from '../context/AuthContext';

function Login() {
  const navigate = useNavigate();
  const { login } = useAuth();

  const [employeeNumber, setEmployeeNumber] = useState('');
  const [password, setPassword] = useState('');
  const [error, setError] = useState('');
  const [isLoading, setIsLoading] = useState(false);

  const handleEmployeeNumberChange = (e) => {
    const value = e.target.value;
    if (value === '' || /^\d+$/.test(value)) {
      setEmployeeNumber(value);
      setError('');
    }
  };

  const handlePasswordChange = (e) => {
    setPassword(e.target.value);
    setError('');
  };

  const handleSubmit = async (e) => {
    e.preventDefault();
    setError('');
    setIsLoading(true);

    const result = await login(employeeNumber, password);
    if (result.success) {
      navigate('/');
    } else {
      setError(result.error);
    }
    setIsLoading(false);
  };

  return (
    <div className="login-page">
      <div className="login-container">
        <div className="login-logo">
          <h1>MaquinadosRBS</h1>
          <p>Sistema de Calidad</p>
        </div>

        <form className="login-form" onSubmit={handleSubmit}>
          <h2>Acceso a Calidad</h2>

          <div className="form-group">
            <label htmlFor="employeeNumber">Número de Empleado</label>
            <input
              type="text"
              id="employeeNumber"
              value={employeeNumber}
              onChange={handleEmployeeNumberChange}
              placeholder="Ingresa tu número de empleado"
              disabled={isLoading}
            />
            <span className="field-hint">Solo valores numéricos</span>
          </div>

          <div className="form-group">
            <label htmlFor="password">Contraseña</label>
            <input
              type="password"
              id="password"
              value={password}
              onChange={handlePasswordChange}
              placeholder="Ingresa tu contraseña"
              disabled={isLoading}
            />
          </div>

          {error && (
            <div className="error-message" role="alert">
              {error}
            </div>
          )}

          <button type="submit" className="login-button" disabled={isLoading}>
            {isLoading ? 'Ingresando...' : 'Iniciar Sesión'}
          </button>
        </form>

        {/* DEBUG TEMPORAL - Eliminar en producción */}
        <div style={{ marginTop: 20, padding: 12, backgroundColor: '#fef9c3', borderRadius: 8, border: '1px solid #facc15', fontSize: 13 }}>
          <strong>Credenciales de prueba:</strong>
          <ul style={{ margin: '6px 0 0 16px', padding: 0 }}>
            <li>Empleado: <code>0001</code> — Usuario de Calidad</li>
            <li>Empleado: <code>0002</code> — Inspector García</li>
            <li>Empleado: <code>0003</code> — Inspector López</li>
          </ul>
          <p style={{ marginTop: 6 }}>Contraseña: <code>Contrasena123</code></p>
        </div>
      </div>
    </div>
  );
}

export default Login;
